/**
 * Measured normalisation (GENERATED by the audio sandbox: `/sandbox/audio/?calibrate=1`, see sandbox/audio).
 * SFX_NORM[id] = 1 / (dry peak of the recipe at unit gain), so `gain = SFX_NORM[id] * dbToGain(recipe.db)`
 * lands the recipe on its authored target peak. MUSIC_NORM / AMB_NORM do the same for RMS of the beds.
 * Missing entries fall back to 1 (and the sandbox report flags them).
 */
export const SFX_NORM: Readonly<Record<string, number>> = {};

export const MUSIC_NORM: Readonly<Record<string, number>> = {};

export const AMB_NORM: Readonly<Record<string, number>> = {};
